/* КОНВЕРТЕР ЕДИНИЦ. Образец ЗАВИСИМЫХ СПИСКОВ: выбрали величину —
   код наполняет списки «из» и «в» её единицами («панель.список»), и тут же
   пересчитывает. Все коэффициенты — к базовой единице величины; температура
   считается отдельно, у неё не только множитель, но и сдвиг. */

const ВИДЫ = {
  'Длина':      {'м': 1, 'км': 1000, 'см': 0.01, 'мм': 0.001, 'дюйм': 0.0254, 'фут': 0.3048,
                 'ярд': 0.9144, 'миля': 1609.344, 'морская миля': 1852},
  'Масса':      {'кг': 1, 'г': 0.001, 'т': 1000, 'мг': 0.000001, 'ц': 100,
                 'фунт': 0.45359237, 'унция': 0.028349523125, 'карат': 0.0002},
  'Площадь':    {'м²': 1, 'км²': 1000000, 'сотка': 100, 'гектар': 10000, 'см²': 0.0001,
                 'мм²': 0.000001, 'акр': 4046.8564224, 'кв. фут': 0.09290304},
  'Объём':      {'л': 0.001, 'мл': 0.000001, 'м³': 1, 'см³': 0.000001,
                 'галлон США': 0.003785411784, 'пинта США': 0.000473176473, 'баррель': 0.158987294928},
  'Скорость':   {'км/ч': 0.2777777777777778, 'м/с': 1, 'миль/ч': 0.44704,
                 'узел': 0.5144444444444444, 'фут/с': 0.3048},
  'Время':      {'ч': 3600, 'мин': 60, 'с': 1, 'мс': 0.001, 'сутки': 86400,
                 'неделя': 604800, 'год': 31557600},
  'Данные':     {'МБ': 1048576, 'КБ': 1024, 'ГБ': 1073741824, 'ТБ': 1099511627776, 'байт': 1, 'бит': 0.125},
  'Давление':   {'бар': 100000, 'атм': 101325, 'Па': 1, 'кПа': 1000,
                 'мм рт. ст.': 133.322387415, 'psi': 6894.757293168},
  'Энергия':    {'кДж': 1000, 'Дж': 1, 'ккал': 4184, 'кал': 4.184, 'кВт·ч': 3600000, 'Вт·ч': 3600},
  'Температура': {'°C': 1, '°F': 1, 'K': 1},
};
const ЕДИНИЦЫ = вид => Object.keys(ВИДЫ[вид] || {});

/* температура: к цельсию и обратно */
const ВЦЕЛЬСИЙ = {'°C': з => з, '°F': з => (з - 32) * 5 / 9, 'K': з => з - 273.15};
const ИЗЦЕЛЬСИЯ = {'°C': з => з, '°F': з => з * 9 / 5 + 32, 'K': з => з + 273.15};

function перевести(вид, из, в, з){
  if(typeof з !== 'number' || !isFinite(з)) return null;
  if(вид === 'Температура'){
    const к = ВЦЕЛЬСИЙ[из], о = ИЗЦЕЛЬСИЯ[в];
    return к && о ? о(к(з)) : null;
  }
  const т = ВИДЫ[вид] || {};
  return т[из] && т[в] ? з * т[из] / т[в] : null;
}

function СменаВида(){
  const п = параметры({});
  const список = ЕДИНИЦЫ(п.вид);
  панель.список('из', список);
  панель.список('в', список);
  панель.поле('из', список[0]);
  панель.поле('в', список.length > 1 ? список[1] : список[0]);
  Пересчитать();
}

function Пересчитать(){
  const п = параметры({});
  const знаков = Math.min(12, Math.max(0, +п.знаков || 0));
  const о = перевести(п.вид, п.из, п.в, +п.знач);
  панель.поле('итог', о === null ? 'выберите единицы'
    : о.toLocaleString('ru-RU', {maximumFractionDigits: знаков}) + ' ' + п.в);
}

/* Выделение целиком: читаем область, переводим числа, пишем полосой обратно.
   Текст и пустые клетки остаются как были. */
async function Выделение(){
  const п = параметры({}), в = книга.выделение;
  if(!в){ панель.сообщение('Сначала выделите клетки'); return; }
  const л = лист(в.лист);
  const строки = await л.прочитать(в.область);
  let переведено = 0;
  const новые = строки.map(р => р.map(з => {
    const о = типЧисло(з) ? перевести(п.вид, п.из, п.в, +з) : null;
    if(о === null) return з;
    переведено++;
    return о;
  }));
  if(!переведено){ панель.сообщение('В ' + в.область + ' нет чисел'); return; }
  л.диапазон(в.область).записать(новые);
  панель.сообщение('Переведено клеток: ' + переведено + ' (' + п.из + ' → ' + п.в + ')');
}
const типЧисло = з => typeof з === 'number' && isFinite(з);

function Старт(){ СменаВида(); }
